C.aJk=new B.A("1. Veri Sorumlusu: Veri sorumlusu uygulamay\u0131 kullanan psikolog/klinik i\u015fletmesidir.\n\n2. \u0130\u015flenen Veriler: Dan\u0131\u015fan ad-soyad, ileti\u015fim bilgileri, de\u011ferlendirme cevaplar\u0131, seans notlar\u0131 ve tedavi plan\u0131 bilgileri.\n\n3. \u0130\u015fleme Amac\u0131: Klinik s\xfcre\xe7 y\xf6netimi, de\u011ferlendirme takibi ve tedavi planlamas\u0131.\n\n4. Saklama: Klinik kay\u0131tlar ba\u011fl\u0131 sunucu hesab\u0131nda ve \xe7al\u0131\u015fma cihaz\u0131ndaki uygulama \xf6nbelle\u011finde saklanabilir. Yetkisiz eri\u015fimi \xf6nlemek i\xe7in hesap bilgilerinizi payla\u015fmay\u0131n.\n\n5. G\xfcvenlik: Uzak eri\u015fim Supabase hesab\u0131, tenant kurallar\u0131 ve Storage eri\u015fim politikalar\u0131yla s\u0131n\u0131rland\u0131r\u0131l\u0131r. Taray\u0131c\u0131daki yerel \xf6nbellek cihaz g\xfcvenli\u011fine ba\u011fl\u0131d\u0131r; ortak cihazlarda oturumu kapat\u0131n ve cihaz \u015fifrelemesini etkinle\u015ftirin.\n\n6. Haklar\u0131n\u0131z: KVKK kapsam\u0131ndaki ba\u015fvuru, d\xfczeltme, silme ve d\u0131\u015fa aktarma talepleri veri sorumlusu psikolog/klinik \xfczerinden y\xfcr\xfct\xfcl\xfcr. Bu ekrandaki yerel s\u0131f\u0131rlama, sunucu yedekleri veya saklama y\xfck\xfcml\xfcl\xfcklerini tek ba\u015f\u0131na ortadan kald\u0131rmaz.\n\nUyar\u0131: Bu uygulama t\u0131bbi tan\u0131 veya tedavi arac\u0131 de\u011fildir; bir sa\u011fl\u0131k profesyonelinin mesleki kararlar\u0131n\u0131 destekleyen bir kay\u0131t arac\u0131d\u0131r.",null,C.aEw,null,null,null,null,null,null,null,null)
